from pathlib import Path
R=Path(__file__).resolve().parents[1]/'resources'
R.mkdir(exist_ok=True)
css='''body{font:16px/1.7 Georgia,serif;color:#33283c;background:#f6f0f8;margin:0;padding:25px}main{max-width:800px;margin:auto;background:white;padding:42px;border:1px solid #d8c8e1}h1{font-size:34px;line-height:1.15;color:#684a83}h2{font-size:22px;margin-top:26px}p,li{font-size:16px}li{margin-bottom:9px}.notice{font-size:13px;color:#76617f}button,a{font:14px/1.4 sans-serif;color:#654778}button{padding:12px 17px;min-height:44px;border:1px solid #b79ac8;background:#f1e8f6;border-radius:5px;cursor:pointer}header{max-width:884px;margin:0 auto 20px;display:flex;justify-content:space-between;align-items:center}a:focus-visible,button:focus-visible{outline:3px solid #76538f;outline-offset:4px}.lines{border-bottom:1px solid #cbbbd3;min-height:80px;margin:13px 0 23px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.cards div{border:1px dashed #a58ab6;padding:30px 15px;text-align:center;font-size:25px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:12px;text-align:left}td{height:45px}@media(max-width:550px){body{padding:15px}main{padding:23px}h1{font-size:29px}.cards{grid-template-columns:1fr 1fr}header{gap:20px}table{font-size:12px}td,th{padding:7px}}@media print{body{background:white;padding:0}header{display:none}main{border:0;padding:12mm;max-width:none}.notice{font-size:12pt}h1{font-size:25pt}p,li{font-size:12pt}h2{break-after:avoid}.cards div{break-inside:avoid}@page{size:A4;margin:12mm}}'''
(R/'resource.css').write_text(css)
def resource(name,title,body):
 (R/name).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Printable sample</title><link rel="stylesheet" href="resource.css"></head><body><header><a href="../index.html#home">← Back to portfolio</a><button onclick="window.print()">Print / Save as PDF</button></header><main><p class="notice">DEMONSTRATION RESOURCE · Editable sample, not evidence of completed teaching</p><h1>{title}</h1>{body}<p class="notice">Make this resource your own. Remove identifying learner information before sharing. To download: choose Print / Save as PDF, then select Save as PDF in your browser’s print dialog.</p></main></body></html>')
resource('sample-lesson.html','Action Verbs · Sample Lesson Plan','''<p><strong>Level:</strong> upper primary / early secondary · <strong>Duration:</strong> 40 minutes<br><strong>Topic:</strong> everyday actions · <strong>Resources:</strong> picture cards, board, worksheet</p><h2>Learning objectives</h2><ul><li>Identify six everyday action verbs: read, write, listen, speak, draw, play.</li><li>Create a complete sentence using “I can…” and an action verb.</li><li>Listen to a partner’s sentence and identify the action described.</li></ul><h2>Lesson sequence</h2><ol><li><strong>Warm-up · 5 minutes:</strong> show or describe familiar activities. Ask what learners can already name.</li><li><strong>Explore · 8 minutes:</strong> match action cards to words. Model pronunciation and a sample sentence.</li><li><strong>Practise · 12 minutes:</strong> pairs take turns choosing a card and describing or miming the action. Offer a seated or spoken alternative.</li><li><strong>Create · 10 minutes:</strong> complete the worksheet, then share three original sentences with a partner.</li><li><strong>Reflect · 5 minutes:</strong> each learner records one new verb and one question on an exit ticket.</li></ol><h2>Support and extension</h2><p>Provide a word bank, visual prompts, extra processing time and paired rehearsal. For extension, use “She can…” or join two actions with “and”. Do not require physical movement.</p><h2>Assessment for learning</h2><p>Listen for accurate verb choice and a complete sentence. Note one class-wide misconception. Give feedback on meaning before minor pronunciation corrections.</p><h2>After-lesson note</h2><p>Which learners could use the target language independently? What should the next lesson revisit?</p><div class="lines"></div>''')
resource('sample-worksheet.html','Action Verbs · Learner Worksheet','''<p><strong>Name or learner code:</strong> ___________________ &nbsp; <strong>Date:</strong> ______________</p><p>Today we are using action words to talk about things we can do. Use this word bank: <strong>read · write · listen · speak · draw · play</strong>.</p><h2>1. Choose the best action word</h2><ol><li>I __________ a story in my book.</li><li>I __________ a picture with my pencil.</li><li>I __________ to a song.</li><li>I __________ a game with my friend.</li></ol><h2>2. Make it your own</h2><p>Write three true sentences. Begin each sentence with “I can…”. You may use the word bank or a different action word.</p><div class="lines"></div><div class="lines"></div><h2>3. Talk with a partner</h2><p>Read one sentence to your partner. Ask: “What can you do?” Listen carefully and write one thing your partner can do.</p><div class="lines"></div><h2>Exit ticket</h2><p>One action word I can use: ___________________<br>One question I still have: ___________________</p><details><summary>Teacher’s answer guide (do not print with learners)</summary><p>Suggested answers for part 1: read, draw, listen, play. Accept other meaningful grammatical answers. Part 2 and part 3 are open responses.</p></details>''')
resource('sample-assessment.html','Assessment & Feedback Template','''<p>Use this simple rubric to check the action-verb lesson. Record learner codes rather than names in shared evidence. This is a blank sample, not assessment data.</p><table><tr><th>Criterion</th><th>Beginning</th><th>Developing</th><th>Independent</th></tr><tr><td>Chooses an appropriate action verb</td><td>Needs examples</td><td>Uses word bank</td><td>Chooses accurately</td></tr><tr><td>Creates an “I can…” sentence</td><td>Needs a model</td><td>Uses a sentence starter</td><td>Creates a complete sentence</td></tr><tr><td>Responds to a partner</td><td>Needs rehearsal</td><td>Responds with support</td><td>Listens and responds</td></tr></table><h2>Observation notes</h2><p>Learner code: ____________ &nbsp; Date: ____________<br>Evidence of learning: ______________________________________</p><div class="lines"></div><h2>Feedback for the learner</h2><p>One thing you did well: _____________________________________<br>One next step to practise: ___________________________________</p><div class="lines"></div><h2>Teacher action</h2><p>What will you adapt for the next lesson? Consider grouping, modelling, vocabulary or additional practice.</p><div class="lines"></div>''')
resource('sample-photo-record.html','Photograph & Consent Record','''<p>This template helps organise portfolio photographs. It is <strong>not a consent form or legal advice</strong>. Follow your school’s policy, applicable law and the approved consent process. Do not publish identifiable minors without appropriate permissions.</p><h2>Image record</h2><p>Image filename: ___________________<br>Date and activity: ___________________<br>Photographer / copyright owner: ___________________<br>Permission or licence checked: ___________________</p><h2>Privacy review</h2><ul><li>Does this photograph identify a learner, including via a name badge, uniform or location?</li><li>Has the school approved the intended online use?</li><li>Where required, is informed parent/guardian consent documented, with appropriate learner assent?</li><li>Are names, student work, screens and contact details hidden or redacted?</li><li>Have location metadata and unnecessary identifying details been removed?</li><li>Would a photograph of materials or an empty room be safer?</li></ul><h2>Publication decision</h2><p>Approved use and expiry: ___________________<br>Reviewer / date: ___________________<br>Caption (avoid learner names): ___________________</p><div class="lines"></div>''')
resource('sample-observation.html','Classroom Observation Sheet','''<p><strong>Date:</strong> ____________ &nbsp; <strong>Class code:</strong> ____________<br><strong>Lesson focus:</strong> _____________________________________</p><p>Observe respectfully and without recording identifying learner details. Use the prompts below to connect classroom practice with your own next steps.</p><h2>Purpose and planning</h2><p>How are the learning objectives made clear? Which task helps learners demonstrate the target language?</p><div class="lines"></div><h2>Participation and inclusion</h2><p>Who contributes? What choices, scaffolds or interaction patterns help different learners participate?</p><div class="lines"></div><h2>Instructions and feedback</h2><p>Note a clear instruction or useful feedback example. Describe what learners did in response.</p><div class="lines"></div><h2>One idea to try</h2><p>What will you adapt for your own class? What support or materials will you need?</p><div class="lines"></div>''')
resource('sample-materials.html','Action Verb Prompt Cards','''<p>Print these cards, cut along the dotted lines and use them for matching, sentence-building or partner practice. Learners can describe an action instead of moving. The cards are deliberately text-only and easy to adapt.</p><div class="cards"><div>READ<br> a story</div><div>WRITE<br> a sentence</div><div>LISTEN<br> to a song</div><div>SPEAK<br> to a friend</div><div>DRAW<br> a picture</div><div>PLAY<br> a game</div></div><h2>Three ways to use the cards</h2><ol><li>Choose a card and complete “I can…” with the action.</li><li>Read a sentence while your partner selects the matching card.</li><li>Join two actions with “and”, then ask a partner what they can do.</li></ol><h2>Adaptation notes</h2><p>Add your own drawings or openly licensed pictures. Use larger type where needed. Replace unfamiliar actions with tasks learners know. Allow extra thinking time before asking for a spoken response.</p>''')
resource('sample-evidence-index.html','Portfolio Evidence Index','''<p>Keep this index alongside your portfolio. Add genuine evidence only after checking permissions and removing private information. These blank rows are a template, not completed evidence.</p><table><tr><th>Evidence ID</th><th>Document / activity</th><th>Objective or claim supported</th><th>Privacy checked</th></tr><tr><td>EV-01</td><td></td><td></td><td></td></tr><tr><td>EV-02</td><td></td><td></td><td></td></tr><tr><td>EV-03</td><td></td><td></td><td></td></tr></table><h2>Before adding a document</h2><ul><li>Does the document support a specific, accurate statement?</li><li>Have names, signatures, contact details and learner identifiers been redacted?</li><li>Do you have permission from the copyright owner and school?</li><li>Is the file readable, dated and clearly titled?</li><li>Is it necessary to publish the full document, or would a redacted excerpt suffice?</li></ul><h2>Reflection link</h2><p>Describe what this evidence taught you and the next step it supports.</p><div class="lines"></div>''')
print('Created 7 genuine printable sample resources')
